      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="10" width="5" height="7" rx="1" /><rect x="15.5" y="10" width="5" height="7" rx="1" /><path d="M9 7l3-3 3 3M9 20l3-2 3 2" />
